import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import App from './App'; // We render the ENTIRE app!
import { server, rest } from './mocks/server';

test('full login flow integration', async () => {
  // Render the whole app with all providers
  render(<App />);

  // Interact with the deeply nested login form
  await userEvent.type(screen.getByLabelText(/username/i), 'admin');
  await userEvent.type(screen.getByLabelText(/password/i), 'password123');
  await userEvent.click(screen.getByRole('button', { name: /login/i }));

  // Assert that the router redirected and the dashboard loaded data from the mock API
  expect(await screen.findByText(/welcome, admin/i)).toBeInTheDocument();
});
